const item = $input.first().json || {};
const norm = $('Normalizar Entrada1').first();
const filt = $('Filtrar Inválidas').first();
const upstream = (filt && filt.json) || (norm && norm.json) || {};

function pickAssistantText(agentJson) {
  const o = agentJson && agentJson.output;
  if (o == null) return '';
  if (typeof o === 'string') return o;
  if (typeof o === 'object') {
    if (typeof o.text === 'string') return o.text;
    if (typeof o.message === 'string') return o.message;
  }
  return '';
}

const p = item.mychatPayload || {};
const number = String(
  p.number || item.phone || upstream.phone || upstream.sessionId || ''
).replace(/\D/g, '');

let msg =
  pickAssistantText(item) ||
  String(item.body || item.message || item.response || '').trim();
if (!msg) msg = String(p.body || '').trim();
msg = msg.replace(/[\r\n]+/g, ' ').trim();

if (!number || !msg) {
  throw new Error(
    'API nao retornou dados para MyChat (numero do webhook + texto em output do AI Agent).'
  );
}

return [{
  json: {
    number,
    body: msg,
    externalKey: p.externalKey || `lead_${number}`,
    isClosed: p.isClosed === true,
  },
}];

const envelope = $json || {};
const body = envelope.body || envelope;
const content = body.content || body.message || body.data?.content || {};
const contact = body.contact || body.sender || body.data?.contact || {};

const doc =
  content.document ||
  content.documentMessage ||
  body.document ||
  body.documentMessage ||
  content.image ||
  body.image ||
  null;

const rawMsg =
  content.text ||
  content.body ||
  content.caption ||
  body.message?.text ||
  body.message ||
  '';

const chatInput = String(rawMsg || '').trim();

let phone = String(
  contact.number ||
  contact.phone ||
  contact.id?.user ||
  body.phone ||
  body.sessionId ||
  ''
).replace(/\D/g, '');

if (!phone) return [{ json: { ignore: true, ignoreReason: 'no_phone' } }];
if (!phone.startsWith('55')) phone = '55' + phone;

const mediaBase64 =
  content.media ||
  content.base64 ||
  doc?.base64 ||
  doc?.data ||
  body.mediaBase64 ||
  body.document?.base64 ||
  body.documentMessage?.base64 ||
  null;

const mimetype = String(
  content.mimetype ||
  content.mimeType ||
  content.mime_type ||
  doc?.mimetype ||
  doc?.mimeType ||
  doc?.mime_type ||
  body.mimetype ||
  ''
).toLowerCase();

const fileName =
  content.fileName ||
  content.filename ||
  content.file_name ||
  doc?.fileName ||
  doc?.filename ||
  doc?.file_name ||
  body.fileName ||
  body.file_name ||
  null;

const hasAny = !!chatInput || !!mediaBase64 || !!mimetype || !!fileName;
if (!hasAny) {
  return [{
    json: {
      ignore: true,
      ignoreReason: 'empty_payload',
      phone,
      sessionId: phone,
      chatInput: '',
    },
  }];
}

return [{
  json: {
    ignore: false,
    phone,
    sessionId: phone,
    chatInput,
    mediaBase64,
    mimetype,
    fileName,
    rawPayload: body,
    history: []
  }
}];
